code.source:
#include <stdio.h>

struct Order {
    char size;
    int qty;
    char type;
};

struct Packed {
    int qty;
    char size;
    char type;
};

union Value {
    int i;
    float f;
    char c;
};

int main(void) {
    printf("char + int + char = %zu bytes\n", sizeof(char) + sizeof(int) + sizeof(char));
    printf("sizeof(struct Order)  = %zu\n", sizeof(struct Order));
    printf("sizeof(struct Packed) = %zu\n", sizeof(struct Packed));
    printf("sizeof(union Value)   = %zu\n\n", sizeof(union Value));

    union Value v;
    v.i = 65;
    printf("v.i = %d\n", v.i);
    v.f = 2.5f;
    printf("v.f = %.1f\n", v.f);
    v.c = 'X';
    printf("v.c = %c\n", v.c);

    return 0;
}

